import 'fake-indexeddb/auto';
import {it,expect,afterEach} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {newId} from '../src/domain/model';
import {ScopedEditorStore,type EditorImage} from '../src/sync/editorStore';
import {valueHash} from '../src/sync/protocol';
const root='/tmp/shinariokanri-independent-rb09-4d14113/independent',all:ScopedEditorStore[]=[];
afterEach(async()=>{for(const s of all.splice(0))await s.delete();});
async function seed(){const s=new ScopedEditorStore(newId());all.push(s);const x=JSON.parse(readFileSync(`${root}/fixtures/R9E00.json`,'utf8')).initial.base as EditorImage;Object.assign(x,{authorizationRevision:'1',authorizationExpiresAt:null});await s.receive(x);return {s,x,id:x.documents.find(d=>Object.hasOwn(d.fields,'name'))!.id};}
it('R9E02B same-revision alteration of an already-common granted field is refused atomically',async()=>{const f=await seed(),before=await f.s.get(f.x.projectId),bad=structuredClone(f.x);bad.documents.find(d=>d.id===f.id)!.fields.name='同一版だが違う値';bad.contentHash=await valueHash(bad.documents);await expect(f.s.receive(bad)).rejects.toMatchObject({code:'REVISION_CHANGED'});expect(await f.s.get(f.x.projectId)).toEqual(before);});
it('R9E02C same-server-revision current field withdrawal removes active editor access and keeps historical input separately',async()=>{const f=await seed();await f.s.saveField(f.x.projectId,f.id,'name','撤回前の未送信入力');const reduced=structuredClone(f.x);delete reduced.documents.find(d=>d.id===f.id)!.fields.name;reduced.contentHash=await valueHash(reduced.documents);await f.s.receive(reduced);const after=(await f.s.get(f.x.projectId))!;expect(after.documents.find(d=>d.id===f.id)!.fields).not.toHaveProperty('name');expect(JSON.stringify(after.retained)).toContain('撤回前の未送信入力');await expect(f.s.saveField(f.x.projectId,f.id,'name','権限外')).rejects.toMatchObject({code:'FORBIDDEN'});writeFileSync(`${root}/fixtures/R9E02C.json`,JSON.stringify({reduced,after},null,2)+'\n');});
it('R9E04 a delayed old same-content-revision fieldset cannot resurrect a grant after the current revoked fieldset was received',async()=>{const f=await seed(),oldResponse=structuredClone(f.x),reduced=structuredClone(f.x);delete reduced.documents.find(d=>d.id===f.id)!.fields.name;reduced.contentHash=await valueHash(reduced.documents);await f.s.receive(reduced);const before=await f.s.get(f.x.projectId);let error;try{await f.s.receive(oldResponse);}catch(e){error=e;}const after=await f.s.get(f.x.projectId);writeFileSync(`${root}/fixtures/R9E04.json`,JSON.stringify({oldResponse,currentReduced:reduced,before,after,error:String(error)},null,2)+'\n');expect(error).toMatchObject({code:'REVISION_CHANGED'});expect(after).toEqual(before);});
